-- Prepared 015: run only in an explicitly authorized disposable rehearsal DB.
begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions,pg_catalog;
select no_plan();
create temporary table ih_ids as select gen_random_uuid() admin,gen_random_uuid() person,gen_random_uuid() shop_a,gen_random_uuid() shop_b,gen_random_uuid() old,gen_random_uuid() recent;
insert into auth.users(id,email,is_anonymous,email_confirmed_at) select admin,'ih-admin@example.invalid',false,now() from ih_ids union all select person,'ih-person@example.invalid',false,now() from ih_ids;
insert into profiles(id,display_name) select admin,'Admin' from ih_ids union all select person,'Account name' from ih_ids;
insert into barbershops(id,name) select shop_a,'Shop A' from ih_ids union all select shop_b,'Shop B' from ih_ids;
insert into barbershop_memberships(user_id,barbershop_id,role,status) select admin,shop_a,'administrator','active' from ih_ids union all select person,shop_a,'barber','active' from ih_ids;
insert into barber_profiles(user_id,barbershop_id,professional_name,active) select person,shop_a,'Different professional name',false from ih_ids;
insert into staff_invitations(id,barbershop_id,recipient_user_id,inviter_user_id,status,created_at,responded_at) select old,shop_a,person,admin,'accepted',now()-interval '3 days',now()-interval '2 days' from ih_ids union all select recent,shop_a,person,admin,'cancelled',now()-interval '1 day',now() from ih_ids;
select set_config('request.jwt.claim.sub',(select admin::text from ih_ids),true);
select set_config('request.jwt.claims',jsonb_build_object('sub',(select admin from ih_ids),'role','authenticated')::text,true);
grant select on ih_ids to authenticated;
set local role authenticated;
create temporary table ih_result as select public.list_shop_staff_invitations((select shop_a from ih_ids)) data;
reset role;
select is(data->0->>'id',(select recent::text from ih_ids),'newest sent invitation first') from ih_result;
select is(data->1->>'id',(select old::text from ih_ids),'oldest sent invitation last') from ih_result;
select is(data->1->>'recipientName','Account name','account profile name rather than professional alias') from ih_result;
select is(data->1->>'barbershopName','Shop A','inviting shop only') from ih_result;
select is(data->1->>'professionalActive','false','accepted invitation can have inactive professional') from ih_result;
select ok(data->1->>'createdAt' is not null and data->1->>'respondedAt' is not null,'real send and acceptance timestamps returned') from ih_result;
select ok(position('recipient_user_id' in data::text)=0 and position('@example' in data::text)=0,'no identity or email leakage') from ih_result;
select throws_ok(format('select public.list_shop_staff_invitations(%L)',(select shop_b from ih_ids)),'42501','FORBIDDEN','cannot read another shop without active admin membership');
update barber_profiles set active=true where barbershop_id=(select shop_a from ih_ids);
select is(public.list_shop_staff_invitations(shop_a)->1->>'professionalActive','true','activity reflects current profile') from ih_ids;
update barbershop_memberships set status='inactive' where user_id=(select person from ih_ids);
select is(public.list_shop_staff_invitations(shop_a)->1->>'professionalActive','false','inactive membership overrides active professional') from ih_ids;
select set_config('request.jwt.claim.sub',(select person::text from ih_ids),true);
select set_config('request.jwt.claims',jsonb_build_object('sub',(select person from ih_ids),'role','authenticated')::text,true);
select ok(not (public.list_own_staff_invitations()->0 ? 'recipientName'),'recipient projection unchanged');
select throws_ok(format('select public.list_shop_staff_invitations(%L)',(select shop_a from ih_ids)),'42501','FORBIDDEN','non admin cannot read administrative history');
select ok(not has_function_privilege('anon','public.list_shop_staff_invitations(uuid)','execute'),'anonymous access remains denied');
select * from finish();
rollback;
